<?php
$suppliers=db()->query('SELECT * FROM suppliers WHERE is_active=1 ORDER BY name')->fetchAll();$products=db()->query('SELECT id,name,sku,stock,purchase_price FROM products WHERE is_active=1 ORDER BY name')->fetchAll();$purchases=db()->query("SELECT pu.*,s.name supplier_name,(SELECT COUNT(*) FROM purchase_items pi WHERE pi.purchase_id=pu.id) item_count FROM purchases pu LEFT JOIN suppliers s ON s.id=pu.supplier_id ORDER BY pu.id DESC LIMIT 100")->fetchAll();
?>
