<section class="admin-card"><div class="admin-card-head"><div><h3>Mal Alışı Gir</h3><p>Tek ürünlü hızlı alış girişi; kayıt stok hareketi oluşturur.</p></div></div><div class="admin-card-body"><form method="post" class="admin-form"><?=csrf_field()?><input type="hidden" name="action" value="save_purchase_v5"><div class="admin-field"><label>Tedarikçi</label><select name="supplier_id"><option value="">Seçin</option><?php foreach($suppliers as $s):?><option value="<?=(int)$s['id']?>"><?=h($s['name'])?></option><?php endforeach;?></select></div><div class="admin-field"><label>Belge / Fatura No</label><input name="document_no"></div><div class="admin-field"><label>Alış Tarihi</label><input type="date" name="purchase_date" value="<?=date('Y-m-d')?>" required></div><div class="admin-field full"><label>Ürün</label><select name="product_id" required><option value="">Ürün seçin</option><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>"><?=h($p['name'].' · '.$p['sku'].' · Stok '.$p['stock'])?></option><?php endforeach;?></select></div><div class="admin-field"><label>Adet</label><input type="number" min="1" name="quantity" value="1" required></div><div class="admin-field"><label>Birim Alış Maliyeti</label><input type="number" min="0" step="0.01" name="unit_cost" required></div><div class="admin-field full"><label>Not</label><textarea name="notes" rows="3"></textarea></div><div class="full"><button class="admin-btn primary large">Mal Alışını Kaydet</button></div></form></div></section>
