</div>
<section class="admin-card"><div class="admin-card-head"><div><h3>Son Alışlar</h3><p>Maliyet ve stok giriş geçmişi</p></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Tarih</th><th>Tedarikçi</th><th>Belge</th><th>Kalem</th><th>Toplam</th><th>Not</th></tr></thead><tbody><?php if(!$purchases):?><tr><td colspan="6"><?=wy_empty('Alış kaydı yok','İlk mal alışını yukarıdaki formdan girebilirsiniz.')?></td></tr><?php endif;?><?php foreach($purchases as $p):?><tr><td><?=h(date('d.m.Y',strtotime($p['purchase_date'])))?></td><td><?=h($p['supplier_name'])?></td><td><?=h($p['document_no'])?></td><td><?=(int)$p['item_count']?></td><td><b><?=money($p['total'])?></b></td><td><?=h($p['notes'])?></td></tr><?php endforeach;?></tbody></table></div></section>